css:
.d-navigation-history{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-navigation-history *,.d-navigation-history *::before,.d-navigation-history *::after{box-sizing:border-box}
.d-navigation-history [hidden]{display:none!important}
.d-navigation-history .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-navigation-history .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-navigation-history label{display:block;margin:8px 0}
.d-navigation-history input,.d-navigation-history select,.d-navigation-history textarea,.d-navigation-history button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-navigation-history input:not([type=checkbox]):not([type=radio]),.d-navigation-history select,.d-navigation-history textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-navigation-history button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-navigation-history button:disabled{opacity:.5;cursor:default}
.d-navigation-history :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-navigation-history [aria-invalid=true]{border-color:var(--warn)!important}
.d-navigation-history .d-scroll{max-width:100%;overflow:auto}
.d-navigation-history table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-navigation-history th,.d-navigation-history td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-navigation-history caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-navigation-history progress{width:100%;accent-color:var(--ink)}
.d-navigation-history pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-navigation-history h3,.d-navigation-history p{margin:8px 0}
.d-navigation-history [aria-pressed=true],.d-navigation-history [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-navigation-history .d-grow{flex:1;min-width:100px}
.d-navigation-history summary{cursor:pointer;padding:6px 0}
.d-navigation-history ul,.d-navigation-history ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{let history=['概览'],cursor=0;const draw=()=>{q('[data-current]').textContent=history[cursor];q('[data-back]').disabled=cursor===0;q('[data-forward]').disabled=cursor===history.length-1;say('访问位置 '+(cursor+1)+' / '+history.length);};qa('[data-go]').forEach(button=>button.onclick=()=>{if(history[cursor]===button.dataset.go)return;history=history.slice(0,cursor+1);history.push(button.dataset.go);cursor++;draw();});q('[data-back]').onclick=()=>{cursor--;draw();};q('[data-forward]').onclick=()=>{cursor++;draw();};draw();})(root, q, qa, say);
}
